import { goalCompletionKey } from '../../goals/model/types';
import type { ConversationPresentation, SessionDetail, SessionMessage } from '../model/types';
import type { InitialConversationState } from './initialConversation';
import { idleStatus } from '../../execution/hooks/useCodexExecution';
import { emptyStatus } from '../../context-management/hooks/useContextManagement';
import { conversationApi } from '../data/conversationApi';
import { mergeMessageList, mergePendingOptimisticMessages, mergeSessionRefresh, sameSubmission } from './conversationMerge';
import { createOptimisticMessage } from './optimisticMessage';
import { readModelCatalog } from '../../models/data/modelCatalogCache';
import { readModelDefaults, resolveVisibleModel, resolveVisibleEffort } from '../../models/model/modelDefaults';

export type ThreadSnapshot = Pick<ConversationPresentation, 'executionStatus' | 'contextStatus' | 'goal' | 'queueItems' | 'userInputRequest'> & {
  session: SessionDetail | null;
};
type Patch = Partial<ThreadSnapshot>;
const persistedPending = (messages: SessionMessage[]) => JSON.stringify(messages.filter(message => message.id.startsWith('optimistic-')
  && (message.deliveryState === 'failed' || message.deliveryState === 'occupied')));
const signature = (value: unknown, omitStream = false) => JSON.stringify(value,
  function (this: { phase?: string; type?: string; id?: string }, key, field) {
    return ['updatedAt', 'lastProbeAt', 'lastEventAt', 'eventEpoch', 'eventSeq', 'durationMs'].includes(key)
      || (omitStream && (['streamingItemId', 'streamingText', 'commentary'].includes(key)
        || (key === 'detail' && this.phase === 'working' && (this.type === 'execution_status' || this.id === 'reasoning-current')))) ? undefined : field;
  });
export const withStreamingStatus = (status: ThreadSnapshot['executionStatus'], live?: ThreadSnapshot['executionStatus']) =>
  status.active && status.turnId && live?.turnId === status.turnId ? { ...status,
    streamingItemId: live.streamingItemId ?? status.streamingItemId, streamingText: live.streamingText ?? status.streamingText,
    commentary: live.commentary ?? status.commentary } : status;
const refreshSession = (current: SessionDetail, incoming: SessionDetail) => {
  const merged = mergeSessionRefresh(current, incoming);
  return merged.messages.length > incoming.messages.length ? { ...merged, hasMore: current.hasMore,
    nextBefore: current.nextBefore, nextCursor: current.nextCursor } : merged;
};

// FEAT-001: one committed record per thread; events and local sends are overlays, never a second cache.
export class ConversationStore {
  committed = new Map<string, ThreadSnapshot>();
  live = new Map<string, Patch>();
  private completedMessages = new Map<string, SessionMessage[]>();
  clearCompletedMessages = (id: string) => { this.completedMessages.delete(id); };
  completeMessage = (id: string, message: SessionMessage) => {
    this.completedMessages.set(id, mergeMessageList(this.completedMessages.get(id) || [], [message]));
    ++this.persistVersion;
    this.notify();
  };
  localPending = new Map<string, SessionMessage[]>();
  sendingQueue = new Map<string, string>();
  private acceptedSubmissions = new Set<string>();
  private rememberAccepted = (id: string, submissionId: string) => {
    this.acceptedSubmissions.add(JSON.stringify([id, submissionId]));
    if (this.acceptedSubmissions.size > 500) this.acceptedSubmissions.delete(this.acceptedSubmissions.values().next().value!);
  };
  private queueDispatches = new Map<string, string>();
  linkQueuedMessage = (id: string, queueSubmissionId: string, submissionId: string) => {
    this.queueDispatches.set(JSON.stringify([id, queueSubmissionId]), submissionId);
    if (this.queueDispatches.size > 500) this.queueDispatches.delete(this.queueDispatches.keys().next().value!);
  };
  private rememberQueue = (id: string, items: ThreadSnapshot['queueItems'], snapshot = false) => {
    for (const item of items) {
      if (item.dispatchSubmissionId && (!snapshot || !this.queueDispatches.has(JSON.stringify([id, item.submissionId])))) this.linkQueuedMessage(id, item.submissionId, item.dispatchSubmissionId);
      const dispatchId = this.queueDispatches.get(JSON.stringify([id, item.submissionId]));
      if (dispatchId && this.acceptedSubmissions.has(JSON.stringify([id, dispatchId]))) this.addMessage(id, {
        ...createOptimisticMessage(item.text, item.attachments, dispatchId, item.sentAt || item.createdAt),
        authorId: item.authorId, authorName: item.authorName, displaySourceAgentId: item.displaySourceAgentId,
      });
    }
  };
  private visibleQueue = (id: string, items: ThreadSnapshot['queueItems']) => items.flatMap(item => {
    const key = JSON.stringify([id, item.submissionId]);
    const dispatchSubmissionId = this.queueDispatches.get(key) || item.dispatchSubmissionId;
    if (this.acceptedSubmissions.has(JSON.stringify([id, dispatchSubmissionId || '']))) this.rememberAccepted(id, item.submissionId);
    if (this.acceptedSubmissions.has(key)) return [];
    return [{ ...item, dispatchSubmissionId }];
  });
  modelChoices = new Map<string, { model: string; reasoningEffort: string }>();
  revisions = new Map<string, number>();
  bodyRevisions = new Map<string, number>();
  private contextNotifications = new Map<string, ReturnType<typeof setTimeout>>();
  synced = new Set<string>();
  dirty = new Set<string>();
  errors = new Map<string, string>();
  dismissedGoals = new Map<string, string>();
  freshBodies = new Set<string>();
  private fieldRevisions = new Map<string, Partial<Record<keyof ThreadSnapshot, number>>>();
  private eventSequences = new Map<string, { epoch: string; seq: number; retired: Set<string> }>();
  acceptEvent = (event: { type: string; threadId?: string; eventEpoch?: string; eventSeq?: number }) => {
    if (!event.eventEpoch || !event.eventSeq) return true;
    const key = `${event.threadId || ''}:${['execution_status', 'assistant_delta', 'assistant_commentary'].includes(event.type) ? 'execution' : event.type}`;
    const previous = this.eventSequences.get(key);
    if (previous?.epoch === event.eventEpoch && event.eventSeq <= previous.seq) return false;
    if (previous?.retired.has(event.eventEpoch)) return false;
    const retired = previous?.retired || new Set<string>();
    if (previous && previous.epoch !== event.eventEpoch) retired.add(previous.epoch);
    this.eventSequences.set(key, { epoch: event.eventEpoch, seq: event.eventSeq, retired });
    return true;
  };
  private listeners = new Set<() => void>();
  private version = 0;
  private persistVersion = 0;
  private reads = new Map<string, { signal: AbortSignal; promise: Promise<ThreadSnapshot> }>();
  private waiters = new Map<string, ((success: boolean) => void)[]>();
  subscribe = (listener: () => void) => { this.listeners.add(listener); return () => { this.listeners.delete(listener); }; };
  getSnapshot = () => this.version;
  getPersistSnapshot = () => this.persistVersion;
  notify = () => { ++this.version; this.listeners.forEach(listener => listener()); };

  constructor(initial: InitialConversationState) {
    for (const id of initial.partialSessionIds) this.freshBodies.add(id);
    for (const detail of initial.cachedSessions) {
      const pending = detail.messages.filter(message => message.id.startsWith('optimistic-'));
      if (pending.length) this.localPending.set(detail.threadId, pending);
      const view = initial.presentation?.[detail.threadId];
      this.committed.set(detail.threadId, { ...this.empty(detail.threadId),
        executionStatus: { ...idleStatus(detail.threadId), ...view?.executionStatus },
        contextStatus: { ...emptyStatus(detail.threadId), ...view?.contextStatus },
        goal: view?.goal || null, queueItems: view?.queueItems || [], userInputRequest: view?.userInputRequest || null,
        session: { ...detail, messages: detail.messages.filter(message => !message.id.startsWith('optimistic-')) } });
    }
  }
  empty = (id: string): ThreadSnapshot => ({ session: null, executionStatus: idleStatus(id), contextStatus: emptyStatus(id),
    goal: null, queueItems: [], userInputRequest: null });
  get = (id: string, includeLive = true): ThreadSnapshot => {
    const value = { ...(this.committed.get(id) || this.empty(id)), ...(includeLive ? this.live.get(id) : {}) };
    const choice = this.modelChoices.get(id);
    if (choice) value.contextStatus = { ...value.contextStatus, ...choice };
    if (!value.session && id) value.session = { threadId: id, source: 'codex', title: '', updatedAt: '', messageCount: null,
      latestUser: '', latestAssistant: '', messages: [] };
    if (value.session && this.completedMessages.has(id)) value.session = { ...value.session,
      messages: mergeMessageList(this.completedMessages.get(id)!, value.session.messages) };
    const pending = this.localPending.get(id);
    if (value.session && pending?.length) value.session = mergePendingOptimisticMessages(value.session, pending);
    value.queueItems = this.visibleQueue(id, value.queueItems).map(item => {
      const sentAt = this.sendingQueue.get(JSON.stringify([id, item.id]));
      const dispatch = sentAt ? this.live.get(id)?.queueItems?.find(queued => queued.id === item.id) : undefined;
      return sentAt && item.state === 'pending' ? { ...item, state: 'dispatching' as const,
        dispatchSubmissionId: dispatch?.dispatchSubmissionId || item.dispatchSubmissionId, sentAt: dispatch?.sentAt || sentAt } : item;
    });
    return value;
  };
  acceptQueuedMessage = (id: string, submissionId: string) => {
    const item = this.get(id).queueItems.find(item => item.submissionId === submissionId || item.dispatchSubmissionId === submissionId);
    this.rememberAccepted(id, submissionId);
    if (item) this.rememberAccepted(id, item.submissionId);
    return item;
  };
  update = (id: string, patch: Patch | ((current: ThreadSnapshot) => Patch), remote = false, deferContext = false) => {
    if (!id) return;
    const next = typeof patch === 'function' ? patch(this.get(id)) : patch;
    this.rememberQueue(id, next.queueItems || []);
    const current = remote ? this.get(id) : (this.committed.get(id) || this.empty(id));
    const keys = Object.keys(next) as (keyof Patch)[];
    if ((remote || keys.every(key => key === 'contextStatus'))
      && keys.every(key => signature(current[key]) === signature(next[key]))) {
      // Retain event ordering even when only its timestamp advanced, without notifying or persisting.
      if (next.contextStatus?.updatedAt && Date.parse(next.contextStatus.updatedAt) > (Date.parse(current.contextStatus.updatedAt || '') || 0)) {
        const target = remote ? this.live.get(id) : this.committed.get(id);
        if (target?.contextStatus) target.contextStatus = { ...target.contextStatus, updatedAt: next.contextStatus.updatedAt };
      }
      return;
    }
    const notify = () => {
      const pending = this.contextNotifications.get(id);
      if (deferContext) {
        // Fixed window: continued usage events never postpone the trailing notification.
        if (!pending) this.contextNotifications.set(id, setTimeout(() => {
          this.contextNotifications.delete(id);
          this.notify();
        }, 180));
      } else {
        if (pending) clearTimeout(pending);
        this.contextNotifications.delete(id);
        this.notify();
      }
    };
    if (!remote || next.contextStatus) {
      this.revisions.set(id, (this.revisions.get(id) || 0) + 1);
      this.fieldRevisions.set(id, { ...this.fieldRevisions.get(id),
        ...Object.fromEntries(keys.map(key => [key, this.revisions.get(id)])) });
    }
    if (remote) {
      this.live.set(id, { ...this.live.get(id), ...next });
      notify();
    } else {
      this.committed.set(id, { ...(this.committed.get(id) || this.empty(id)), ...next });
      if (next.session) this.bodyRevisions.set(id, this.revisions.get(id)!);
      ++this.persistVersion;
      const live = this.live.get(id);
      if (live) for (const key of Object.keys(next) as (keyof Patch)[]) delete live[key];
      notify();
    }
  };
  invalidate = (id: string, notify = true) => {
    this.revisions.set(id, (this.revisions.get(id) || 0) + 1);
    this.bodyRevisions.set(id, this.revisions.get(id)!);
    this.dirty.add(id);
    if (notify) this.notify();
  };
  request = (id: string) => {
    const promise = new Promise<boolean>(resolve => this.waiters.set(id, [...(this.waiters.get(id) || []), resolve]));
    this.invalidate(id);
    return promise;
  };
  finish = (id: string, error = '') => {
    if (error) this.errors.set(id, error); else this.errors.delete(id);
    for (const resolve of this.waiters.get(id) || []) resolve(!error);
    this.waiters.delete(id);
  };
  read = (id: string, sourceRevision: string, signal: AbortSignal, conversationId?: string) => {
    const pending = this.reads.get(id);
    if (pending && !pending.signal.aborted) return pending.promise;
    const promise = conversationApi.snapshot(id, sourceRevision, signal, conversationId).then(result => {
      const current = this.committed.get(id)?.session;
      const incoming = result.session;
      const session = incoming && current ? current.contentVersion && incoming.contentVersion && current.contentVersion > incoming.contentVersion
        ? current : refreshSession(current, incoming) : incoming || current || null;
      if (!session) throw new Error('对话同步失败，保留已有内容');
      const selectedSettings = this.committed.get(id)?.contextStatus.selectedSettings;
      const saved = selectedSettings || result.context.lastSuccessfulSettings;
      const models = readModelCatalog(), defaults = readModelDefaults();
      const model = saved ? resolveVisibleModel(models, defaults, saved.model, '') : result.context.model;
      const contextStatus = saved ? { ...result.context, model, selectedSettings,
        reasoningEffort: resolveVisibleEffort(models, defaults, model, saved.reasoningEffort) } : result.context;
      return { session: { ...session, ...(incoming && result.historyFormatVersion ? { historyFormatVersion: result.historyFormatVersion } : {}), sourceRevision: result.sourceRevision || session.sourceRevision }, contextStatus,
        executionStatus: result.status, goal: result.goal, queueItems: result.queue, userInputRequest: result.input };
    });
    const entry = { signal, promise };
    this.reads.set(id, entry);
    void promise.finally(() => { if (this.reads.get(id) === entry) this.reads.delete(id); }).catch(() => {});
    return promise;
  };
  commit = (id: string, snapshot: ThreadSnapshot, revision: number) => {
    const previousCommitted = this.committed.get(id);
    const previousPending = this.localPending.get(id);
    const previousLive = signature(this.live.get(id), true);
    const hadError = this.errors.has(id);
    const wasDirty = this.dirty.has(id);
    const wasSynced = this.synced.has(id);
    this.rememberQueue(id, snapshot.queueItems, true);
    for (const message of snapshot.session?.messages || []) if (message.role === 'user' && message.submissionId && !message.id.startsWith('optimistic-')) this.rememberAccepted(id, message.submissionId);
    snapshot = { ...snapshot, queueItems: this.visibleQueue(id, snapshot.queueItems) };
    if (snapshot.goal?.status === 'complete' && this.dismissedGoals.get(id) === goalCompletionKey(snapshot.goal)) snapshot = { ...snapshot, goal: null };
    const latest = this.committed.get(id);
    for (const [key, changedAt] of Object.entries(this.fieldRevisions.get(id) || {}) as [keyof ThreadSnapshot, number][]) {
      if (changedAt <= revision) continue;
      const context = key === 'contextStatus' ? this.live.get(id)?.contextStatus : undefined;
      if (context) snapshot = { ...snapshot, contextStatus: { ...context,
        model: snapshot.contextStatus.model, reasoningEffort: snapshot.contextStatus.reasoningEffort,
        selectedSettings: snapshot.contextStatus.selectedSettings } };
      else {
        const patch = this.live.get(id);
        if (patch && key in patch) snapshot = { ...snapshot, [key]: patch[key] };
        else if (latest) snapshot = { ...snapshot, [key]: latest[key] };
      }
    }
    const current = latest?.session;
    if (current && snapshot.session) snapshot = { ...snapshot, session: refreshSession(current, snapshot.session) };
    const pending = this.localPending.get(id);
    if (pending && snapshot.session) {
      const ids = new Set(snapshot.session.messages.map(message => message.id));
      const merged = mergePendingOptimisticMessages(snapshot.session, pending);
      snapshot = { ...snapshot, session: { ...merged, messages: merged.messages.filter(message => ids.has(message.id)) } };
    }
    this.committed.set(id, snapshot);
    const local = this.localPending.get(id);
    if (local && snapshot.session) {
      const remaining = mergePendingOptimisticMessages(snapshot.session, local).messages.filter(message => message.id.startsWith('optimistic-'));
      if (remaining.length) this.localPending.set(id, remaining); else this.localPending.delete(id);
    }
    const live = this.live.get(id);
    if (live?.contextStatus) live.contextStatus = { ...live.contextStatus,
      model: snapshot.contextStatus.model, reasoningEffort: snapshot.contextStatus.reasoningEffort };
    this.synced.add(id);
    if (live && (this.bodyRevisions.get(id) || 0) <= revision) {
      const executionStatus = withStreamingStatus(snapshot.executionStatus, live.executionStatus);
      for (const key of Object.keys(live) as (keyof Patch)[]) {
        if ((this.fieldRevisions.get(id)?.[key] || 0) <= revision) delete live[key];
      }
      if (executionStatus !== snapshot.executionStatus) live.executionStatus = executionStatus;
      if (!Object.keys(live).length) this.live.delete(id);
    }
    if ((this.bodyRevisions.get(id) || 0) <= revision) {
      this.dirty.delete(id); this.freshBodies.delete(id);
    }
    this.finish(id);
    const dataChanged = signature(previousCommitted, true) !== signature(this.committed.get(id), true)
      || signature(previousPending, true) !== signature(this.localPending.get(id), true);
    if (!dataChanged && previousCommitted) this.committed.set(id, previousCommitted);
    const stateChanged = hadError !== this.errors.has(id) || wasDirty !== this.dirty.has(id)
      || wasSynced !== this.synced.has(id) || previousLive !== signature(this.live.get(id), true);
    if (dataChanged) ++this.persistVersion;
    return dataChanged || stateChanged;
  };
  addMessage = (id: string, message: SessionMessage) => {
    if ([...(this.committed.get(id)?.session?.messages || []), ...(this.localPending.get(id) || [])].some(item => item.id === message.id || sameSubmission(item, message))) return;
    if (!this.committed.has(id)) this.committed.set(id, this.empty(id));
    this.localPending.set(id, mergeMessageList(this.localPending.get(id) || [], [message]));
    if (message.id.startsWith('optimistic-') && (message.deliveryState === 'failed' || message.deliveryState === 'occupied')) ++this.persistVersion;
    this.notify();
  };
  changeMessages = (id: string, update: (messages: SessionMessage[]) => SessionMessage[]) => {
    const current = this.localPending.get(id) || [], before = persistedPending(current), next = update(current);
    if (current.length === next.length && current.every((message, index) => message === next[index])) return;
    if (before !== persistedPending(next)) ++this.persistVersion;
    if (next.length) this.localPending.set(id, next); else this.localPending.delete(id);
    this.notify();
  };
  setArchived = (id: string, archived: boolean) => {
    this.finish(id);
    const session = this.committed.get(id)?.session;
    if (session) this.update(id, { session: { ...session, archived } }); else this.notify();
  };
  migrate = (from: string, to: string, detail: SessionDetail) => {
    const previous = this.get(from, false), existing = this.get(to, false);
    this.committed.set(to, { ...previous, ...existing, session: detail,
      queueItems: [...new Map([...previous.queueItems, ...existing.queueItems].map(item => [item.id, { ...item, threadId: to }])).values()],
      executionStatus: { ...previous.executionStatus, threadId: to }, contextStatus: { ...previous.contextStatus, threadId: to } });
    this.localPending.set(to, mergeMessageList(this.localPending.get(to) || [], this.localPending.get(from) || []));
    const choice = this.modelChoices.get(from);
    if (choice) this.modelChoices.set(to, choice);
    this.committed.delete(from); this.live.delete(from); this.localPending.delete(from); this.modelChoices.delete(from);
    this.dirty.delete(from); this.revisions.delete(from); this.errors.delete(from); this.synced.delete(from);
    this.fieldRevisions.delete(from); this.freshBodies.delete(from); this.bodyRevisions.delete(from);
    clearTimeout(this.contextNotifications.get(from)); this.contextNotifications.delete(from);
    ++this.persistVersion;
    this.notify();
  };
}

import { useCallback, useEffect, useRef, useState } from "react";
import type { MutableRefObject } from "react";
import { hasAccessToken } from "../../../shared/api/http";
import { conversationApi } from "../data/conversationApi";
import type { ProjectInfo, SessionDetail, SessionSummary } from "../model/types";
import type { InitialConversationState } from "../state/initialConversation";
import { readLocalCache } from "../../../shared/state/localCache";
import { readModelCatalog } from "../../models/data/modelCatalogCache";
import { providerIdOf, readModelDefaults, resolveVisibleModel } from "../../models/model/modelDefaults";

interface ConversationSelection {
  setArchived: (threadId: string, archived: boolean) => void;
  selectedIdRef: MutableRefObject<string>;
  loadSession: (threadId: string, options?: { older?: boolean; retry?: boolean; recovery?: boolean; prefetch?: boolean }) => Promise<boolean>;
  adoptSelection: (threadId: string) => Promise<boolean>;
  clearSelection: () => void;
  selectSession: (threadId: string) => void;
  setCreatedSession: (detail: SessionDetail, preserveComposer?: boolean) => void;
  setSessionError: (message: string) => void;
  cacheCreatedSession: (detail: SessionDetail, previousId?: string) => void;
}

interface RemovedSession {
  session: SessionSummary;
  index: number;
  archivedView: boolean;
}

const archiveIconFeedbackMs = 110;
const waitForArchiveIconFeedback = () => new Promise<void>((resolve) => {
  window.setTimeout(resolve, archiveIconFeedbackMs);
});

const sameSessionSummary = (left: SessionSummary, right: SessionSummary) => (
  left.threadId === right.threadId
  && left.sourceRevision === right.sourceRevision
  && left.source === right.source
  && left.title === right.title
  && left.updatedAt === right.updatedAt
  && left.messageCount === right.messageCount
  && left.latestUser === right.latestUser
  && left.latestAssistant === right.latestAssistant
  && left.latestMessage === right.latestMessage
  && left.archived === right.archived
  && left.archivable === right.archivable
  && left.conversationKind === right.conversationKind
  && left.createdBy === right.createdBy
  && left.readOnly === right.readOnly
  && left.forkedFromId === right.forkedFromId
  && left.cwd === right.cwd
);

const sameSessionList = (left: SessionSummary[], right: SessionSummary[]) => (
  left.length === right.length && left.every((session, index) => sameSessionSummary(session, right[index]))
);

export function useConversationCatalog(
  initial: InitialConversationState,
  selection: ConversationSelection,
  currentModel: string,
) {
  const initialArchivedView = new URLSearchParams(window.location.search).get("archived") === "1";
  const [project, setProject] = useState<ProjectInfo | null>(null);
  const [sessions, setSessions] = useState<SessionSummary[]>(initialArchivedView ? [] : initial.sessions);
  const [loadingList, setLoadingList] = useState(initialArchivedView || !initial.sessions.length);
  const [initialSyncReady, setInitialSyncReady] = useState(false);
  // FEAT-001: confirmed archive results outrank stale directory associations.
  const [archivedByThread, setArchivedByThread] = useState<Record<string, boolean>>({});
  const [archivedView, setArchivedView] = useState(initialArchivedView);
  const [creating, setCreating] = useState(false);
  const [archiveBusyIds, setArchiveBusyIds] = useState<ReadonlySet<string>>(() => new Set());
  const [listError, setListError] = useState("");
  const sessionsRef = useRef(sessions);
  sessionsRef.current = sessions;
  const archivedViewRef = useRef(initialArchivedView);
  const viewCacheRef = useRef(new Map<boolean, SessionSummary[]>());
  const archiveSwitchTimerRef = useRef(0);
  const creatingRef = useRef(new Set<string>());
  const archiveBusyIdsRef = useRef(new Set<string>());
  const listRequestRef = useRef(0);
  const listAbortControllerRef = useRef<AbortController | null>(null);
  const transientSessionsRef = useRef(new Map<string, SessionSummary>());

  const refreshSessions = useCallback(async (initialLoad = false, changedThreadId?: string, reloadSelected = true) => {
    const requestId = ++listRequestRef.current;
    const requestedArchivedView = archivedViewRef.current;
    listAbortControllerRef.current?.abort();
    const controller = new AbortController();
    listAbortControllerRef.current = controller;
    if (initialLoad) setLoadingList(true);
    setListError("");
    try {
      let serverSessions = (await conversationApi.sessions(requestedArchivedView, controller.signal))
        .filter((item) => !archiveBusyIdsRef.current.has(item.threadId));
      if (requestId !== listRequestRef.current || requestedArchivedView !== archivedViewRef.current) return;

      setArchivedByThread(previous => {
        const changed = serverSessions.filter(item => previous[item.threadId] !== Boolean(item.archived));
        return changed.length ? { ...previous, ...Object.fromEntries(changed.map(item => [item.threadId, Boolean(item.archived)])) } : previous;
      });
      const serverIds = new Set(serverSessions.map((item) => item.threadId));
      for (const threadId of serverIds) transientSessionsRef.current.delete(threadId);
      const transientSessions = archivedViewRef.current
        ? []
        : Array.from(transientSessionsRef.current.values()).reverse();
      const nextSessions = [...transientSessions, ...serverSessions];
      viewCacheRef.current.set(requestedArchivedView, nextSessions);
      if (!sameSessionList(sessionsRef.current, nextSessions)) {
        sessionsRef.current = nextSessions;
        setSessions(nextSessions);
      }
      if (requestedArchivedView) {
        if (selection.selectedIdRef.current) selection.clearSelection();
        return;
      }
      const requestedId = new URLSearchParams(window.location.search).get("thread") || "";
      const currentId = selection.selectedIdRef.current;
      const agentScoped = Boolean(new URLSearchParams(window.location.search).get("agent"));
      if (agentScoped) {
        const pinnedId = requestedId || currentId;
        if (!pinnedId) return;
        if (currentId !== pinnedId) await selection.adoptSelection(pinnedId);
        else if (reloadSelected && (!changedThreadId || changedThreadId === pinnedId)) {
          await selection.loadSession(pinnedId);
        }
        return;
      }
      const nextId = nextSessions.some((item) => item.threadId === requestedId)
        ? requestedId
        : currentId || nextSessions[0]?.threadId || "";
      if (!nextId) {
        selection.clearSelection();
        return;
      }
      const selectionChanged = nextId !== currentId;
      if (selectionChanged) await selection.adoptSelection(nextId);
      else if (reloadSelected && (!changedThreadId || changedThreadId === nextId)) {
        await selection.loadSession(nextId);
      }
    } catch (reason) {
      if (controller.signal.aborted) return;
      if (requestId !== listRequestRef.current || requestedArchivedView !== archivedViewRef.current) return;
      setListError(reason instanceof Error ? reason.message : String(reason));

    } finally {
      if (listAbortControllerRef.current === controller) listAbortControllerRef.current = null;
      if (!controller.signal.aborted && requestId === listRequestRef.current && requestedArchivedView === archivedViewRef.current) {
        setLoadingList(false);
      }
    }
  }, [selection.adoptSelection, selection.clearSelection, selection.loadSession, selection.selectedIdRef]);

  const updateArchiveQuery = useCallback((archived: boolean) => {
    const params = new URLSearchParams(window.location.search);
    if (archived) params.set("archived", "1");
    else params.delete("archived");
    params.delete("thread");
    const query = params.toString();
    window.history.replaceState(null, "", `${window.location.pathname}${query ? `?${query}` : ""}`);
  }, []);

  const setArchiveViewMode = useCallback(async (archived: boolean) => {
    if (archived === archivedViewRef.current) return;
    window.clearTimeout(archiveSwitchTimerRef.current);
    listAbortControllerRef.current?.abort();
    ++listRequestRef.current;
    viewCacheRef.current.set(archivedViewRef.current, sessionsRef.current);
    archivedViewRef.current = archived;
    setArchivedView(archived);
    const cached = viewCacheRef.current.get(archived);
    sessionsRef.current = cached || [];
    setSessions(cached || []);
    setLoadingList(!cached);
    setListError("");
    selection.clearSelection();
    updateArchiveQuery(archived);
    archiveSwitchTimerRef.current = window.setTimeout(() => {
      void refreshSessions(!cached, undefined, false);
    }, 180);
  }, [refreshSessions, selection.clearSelection, updateArchiveQuery]);

  useEffect(() => {
    if (!hasAccessToken) {
      setLoadingList(false);
      setListError("访问链接缺少令牌，请运行 pnpm start:demo 并打开输出的完整链接");
      setInitialSyncReady(true);
      return;
    }
    let cancelled = false;
    const controller = new AbortController();
    const hasCachedList = Boolean(initial.sessions.length);
    void Promise.allSettled([
      conversationApi.project(controller.signal).then(setProject),
      refreshSessions(!hasCachedList, undefined, false),
    ]).then((results) => {
      if (cancelled || controller.signal.aborted) return;
      const rejected = results.find((result): result is PromiseRejectedResult => result.status === "rejected");
      if (rejected) {
        const reason = rejected.reason;
        setListError(reason instanceof Error ? reason.message : String(reason));
      }
    }).finally(() => {
      if (cancelled) return;
      setInitialSyncReady(true);
    });
    return () => {
      cancelled = true;
      controller.abort();
    };
  }, [initial, refreshSessions, selection.loadSession]);

  const createSession = useCallback(async (projectRoot = "", requestedModel = "", pendingId = "", requestedProviderId = "", preserveComposer = false) => {
    const createKey = pendingId || "new";
    if (creatingRef.current.has(createKey)) {
      if (pendingId && selection.selectedIdRef.current === pendingId) selection.setSessionError("新对话创建失败，请重试");
      return "";
    }
    creatingRef.current.add(createKey);
    setCreating(true);
    setListError("");
    try {
      if (archivedViewRef.current) {
        archivedViewRef.current = false;
        setArchivedView(false);
        sessionsRef.current = [];
        setSessions([]);
        if (selection.selectedIdRef.current !== pendingId) selection.clearSelection();
        updateArchiveQuery(false);
      }
      const preferredModel = readLocalCache("negus-preferred-model-v1", (value): value is string => typeof value === "string");
      const defaultModel = requestedModel
        ? ""
        : resolveVisibleModel(readModelCatalog(), readModelDefaults(), "", "");
      const model = requestedModel || defaultModel || preferredModel || currentModel;
      const catalogEntry = readModelCatalog().find((entry) => entry.model === model);
      const providerId = requestedProviderId || (catalogEntry ? providerIdOf(catalogEntry) : readModelDefaults().providerId);
      const created = await conversationApi.create(model, projectRoot, providerId);
      const detail: SessionDetail = { ...created, messages: [] };
      selection.cacheCreatedSession(detail, pendingId);
      transientSessionsRef.current.set(created.threadId, created);
      const stillCurrent = !pendingId || selection.selectedIdRef.current === pendingId;
      if (stillCurrent) {
        selection.setCreatedSession(detail, preserveComposer);
      }
      const nextSessions = [created, ...sessionsRef.current.filter((item) => item.threadId !== created.threadId)];
      sessionsRef.current = nextSessions;
      setSessions(nextSessions);
      return created.threadId;
    } catch (reason) {
      const message = reason instanceof Error ? reason.message : String(reason);
      setListError(message);
      if (pendingId && selection.selectedIdRef.current === pendingId) selection.setSessionError(message);
      return "";
    } finally {
      creatingRef.current.delete(createKey);
      setCreating(creatingRef.current.size > 0);
    }
  }, [currentModel, selection.clearSelection, selection.selectedIdRef, selection.setCreatedSession, selection.setSessionError, updateArchiveQuery]);

  const forkSession = useCallback(async (threadId: string, lastTurnId: string, preserveComposer = false) => {
    setListError("");
    try {
      const result = await conversationApi.fork(threadId, lastTurnId);
      const created = result.session;
      const detail: SessionDetail = { ...created, archived: false, messages: [] };
      selection.cacheCreatedSession(detail);
      transientSessionsRef.current.set(created.threadId, created);
      archivedViewRef.current = false;
      setArchivedView(false);
      updateArchiveQuery(false);
      const nextSessions = [created, ...sessionsRef.current.filter((item) => item.threadId !== created.threadId)];
      sessionsRef.current = nextSessions;
      setSessions(nextSessions);
      selection.setCreatedSession(detail, preserveComposer);
      await selection.loadSession(created.threadId);
      return true;
    } catch (reason) {
      setListError(reason instanceof Error ? reason.message : String(reason));
      return false;
    }
  }, [selection.loadSession, selection.setCreatedSession, updateArchiveQuery]);

  const beginArchiveOperation = useCallback((threadId: string) => {
    if (archiveBusyIdsRef.current.has(threadId)) return false;
    const next = new Set(archiveBusyIdsRef.current);
    next.add(threadId);
    archiveBusyIdsRef.current = next;
    setArchiveBusyIds(next);
    return true;
  }, []);

  const finishArchiveOperation = useCallback((threadId: string) => {
    const next = new Set(archiveBusyIdsRef.current);
    next.delete(threadId);
    archiveBusyIdsRef.current = next;
    setArchiveBusyIds(next);
  }, []);

  const removeSessionOptimistically = useCallback((threadId: string): RemovedSession | null => {
    const index = sessionsRef.current.findIndex((item) => item.threadId === threadId);
    if (index < 0) return null;
    const removed = { session: sessionsRef.current[index], index, archivedView: archivedViewRef.current };
    const next = sessionsRef.current.filter((item) => item.threadId !== threadId);
    sessionsRef.current = next;
    setSessions(next);
    return removed;
  }, []);

  const restoreRemovedSession = useCallback((removed: RemovedSession | null) => {
    if (!removed || removed.archivedView !== archivedViewRef.current) return;
    if (sessionsRef.current.some((item) => item.threadId === removed.session.threadId)) return;
    const next = [...sessionsRef.current];
    next.splice(Math.min(removed.index, next.length), 0, removed.session);
    sessionsRef.current = next;
    setSessions(next);
  }, []);

  const archiveSession = useCallback(async (threadId: string) => {
    if (!beginArchiveOperation(threadId)) return false;
    listAbortControllerRef.current?.abort();
    ++listRequestRef.current;
    let removed: RemovedSession | null = null;
    let requestFailed = false;
    let requestError: unknown;
    setListError("");
    try {
      const request = conversationApi.archive(threadId).catch((reason) => {
        requestFailed = true;
        requestError = reason;
      });
      await waitForArchiveIconFeedback();
      if (requestFailed) throw requestError;
      removed = removeSessionOptimistically(threadId);
      setArchivedByThread(previous => ({ ...previous, [threadId]: true }));
      await request;
      if (requestFailed) throw requestError;
      listAbortControllerRef.current?.abort();
      ++listRequestRef.current;
      selection.setArchived(threadId, true);
      setArchivedByThread(previous => ({ ...previous, [threadId]: true }));
      window.dispatchEvent(new CustomEvent("negus:conversation-archived", { detail: { threadId } }));
      transientSessionsRef.current.delete(threadId);
      viewCacheRef.current.delete(true);
      if (selection.selectedIdRef.current === threadId) selection.clearSelection();
      return true;
    } catch (reason) {
      restoreRemovedSession(removed);
      setArchivedByThread(previous => ({ ...previous, [threadId]: false }));
      setListError(reason instanceof Error ? reason.message : String(reason));
      return false;
    } finally {
      finishArchiveOperation(threadId);
    }
  }, [beginArchiveOperation, finishArchiveOperation, removeSessionOptimistically, restoreRemovedSession, selection.clearSelection, selection.selectedIdRef]);

  const unarchiveSession = useCallback(async (threadId: string) => {
    if (!beginArchiveOperation(threadId)) return false;
    listAbortControllerRef.current?.abort();
    ++listRequestRef.current;
    let removed: RemovedSession | null = null;
    let requestFailed = false;
    let requestError: unknown;
    setListError("");
    try {
      const request = conversationApi.unarchive(threadId).catch((reason) => {
        requestFailed = true;
        requestError = reason;
      });
      await waitForArchiveIconFeedback();
      if (requestFailed) throw requestError;
      removed = removeSessionOptimistically(threadId);
      setArchivedByThread(previous => ({ ...previous, [threadId]: false }));
      await request;
      if (requestFailed) throw requestError;
      listAbortControllerRef.current?.abort();
      ++listRequestRef.current;
      selection.setArchived(threadId, false);
      setArchivedByThread(previous => ({ ...previous, [threadId]: false }));
      viewCacheRef.current.delete(false);
      if (selection.selectedIdRef.current === threadId) selection.clearSelection();
      return true;
    } catch (reason) {
      restoreRemovedSession(removed);
      setArchivedByThread(previous => ({ ...previous, [threadId]: true }));
      setListError(reason instanceof Error ? reason.message : String(reason));
      return false;
    } finally {
      finishArchiveOperation(threadId);
    }
  }, [beginArchiveOperation, finishArchiveOperation, removeSessionOptimistically, restoreRemovedSession, selection.clearSelection, selection.selectedIdRef]);

  useEffect(() => () => {
    window.clearTimeout(archiveSwitchTimerRef.current);
    listAbortControllerRef.current?.abort();
  }, []);

  const selectLatestSession = useCallback((excludeThreadId = "") => {
    const pick = (list: SessionSummary[]) => list.find((session) => !session.archived && session.threadId !== excludeThreadId)
      || list.find((session) => !session.archived);
    if (archivedViewRef.current) {
      const latest = pick(viewCacheRef.current.get(false) || []);
      void setArchiveViewMode(false).then(() => {
        if (latest) selection.selectSession(latest.threadId);
      });
      return;
    }
    const latest = pick(sessionsRef.current);
    if (latest) selection.selectSession(latest.threadId);
  }, [selection.selectSession, setArchiveViewMode]);

  const updateSessionSummary = useCallback((summary: Pick<SessionSummary, "threadId"> & Partial<SessionSummary>) => {
    listAbortControllerRef.current?.abort();
    ++listRequestRef.current;
    setLoadingList(false);
    const update = (items: SessionSummary[]) => items.map(item => item.threadId === summary.threadId ? { ...item, ...summary } : item);
    sessionsRef.current = update(sessionsRef.current);
    setSessions(sessionsRef.current);
    if (transientSessionsRef.current.has(summary.threadId)) transientSessionsRef.current.set(summary.threadId, { ...transientSessionsRef.current.get(summary.threadId)!, ...summary });
    for (const [key, items] of viewCacheRef.current) viewCacheRef.current.set(key, update(items));
  }, []);

  return {
    updateSessionSummary,
    project,
    sessions,
    archivedView,
    loadingList,
    initialSyncReady,
    creating,
    archiveBusyIds,
    archivedByThread,
    listError,
    refreshSessions,
    setArchiveViewMode,
    createSession,
    forkSession,
    archiveSession,
    unarchiveSession,
    selectLatestSession,
  };
}

import { currentConversationId } from "../../../shared/api/conversationScope";
import { modelApi } from "../../models/data/modelApi";
import { HttpError } from "../../../shared/api/http";
import { useCallback, useEffect, useRef, useState } from "react";
import type { MediaFile } from "../../../shared/model/media";
import type { RealtimeRecoveryReason } from "../../../shared/model/realtime";
import { useContextManagement } from "../../context-management/hooks/useContextManagement";
import { executionApi } from "../../execution/data/executionApi";
import { useCodexExecution } from "../../execution/hooks/useCodexExecution";
import type { ProjectEvent, UserInputRequest } from "../../execution/model/types";
import { useModels } from "../../models/hooks/useModels";
import { readModelCatalog } from "../../models/data/modelCatalogCache";
import { providerIdOf, readModelDefaults, resolveVisibleEffort, resolveVisibleModel, useModelDefaults } from "../../models/model/modelDefaults";
import { conversationApi } from "../data/conversationApi";
import { useConversationEvents } from "../realtime/useConversationEvents";
import { createOptimisticMessage, createSubmissionId } from "../state/optimisticMessage";
import { readInitialConversationState } from "../state/initialConversation";
import { useConversationCatalog } from "./useConversationCatalog";
import { presentConversationError, useConversationSession } from "./useConversationSession";
import { useFollowUpQueue } from "./useFollowUpQueue";
import { useThreadGoal } from "../../goals/hooks/useThreadGoal";
import type { SessionMessage, SessionSummary } from "../model/types";
import { createClientId } from "../../../shared/id/clientId";
import { readLocalCache, writeLocalCache } from "../../../shared/state/localCache";
import { isPendingThread } from "../model/pendingThread";

const attachmentsFromMessage = (message: SessionMessage): MediaFile[] => {
  const attachments = new Map<string, MediaFile>();
  for (const block of message.blocks || []) {
    if ("file" in block && block.file) attachments.set(block.file.id, block.file);
  }
  return [...attachments.values()];
};

const conversationLocationKey = () => {
  const params = new URLSearchParams(window.location.search);
  return JSON.stringify([
    params.get("thread") || "",
    params.get("agent") || "",
    params.get("employee") || "",
    params.get("conversation") || "",
    params.get("archived") === "1",
  ]);
};

export function useProjectConversations() {
  const conversationScope = currentConversationId();
  const [initial] = useState(readInitialConversationState);
  const selection = useConversationSession(initial);
  const serverThreadId = isPendingThread(selection.selectedId) ? "" : selection.selectedId;

  const execution = useCodexExecution(serverThreadId, selection.store);
  const followUpQueue = useFollowUpQueue(serverThreadId, selection.store);
  const goal = useThreadGoal(serverThreadId, selection.store);
  const [forkingMessageId, setForkingMessageId] = useState("");
  const [editingMessage, setEditingMessage] = useState<SessionMessage | null>(null);
  const editingMessageRef = useRef<SessionMessage | null>(null);
  const desktopPreparingRef = useRef<Promise<boolean> | null>(null);
  const [renaming, setRenaming] = useState(false);
  const [retryingMessageId, setRetryingMessageId] = useState("");
  const [localSendVersion, setLocalSendVersion] = useState(0);
  const [historyEdit, setHistoryEdit] = useState<{ threadId: string; revision: number } | null>(null);
  const [providerSwitch, setProviderSwitch] = useState<{
    threadId: string;
    title: string;
    model: string;
    reasoningEffort: string;
    providerName: string;
  } | null>(null);
  const [providerSwitchBusy, setProviderSwitchBusy] = useState(false);
  const [providerSwitchError, setProviderSwitchError] = useState("");
  const userInputRequest = selection.store.get(serverThreadId).userInputRequest;
  const setUserInputRequest = useCallback((value: UserInputRequest | null | ((current: UserInputRequest | null) => UserInputRequest | null)) => {
    const id = selection.selectedIdRef.current;
    selection.store.update(id, { userInputRequest: typeof value === 'function' ? value(selection.store.get(id).userInputRequest) : value });
  }, [selection.store]);
  const [userInputBusy, setUserInputBusy] = useState(false);
  const [userInputError, setUserInputError] = useState("");
  const reconcilingSubmissionsRef = useRef(new Set<string>());
  const reconciledSubmissionsRef = useRef(new Set<string>());
  const realtimeRecoveryRef = useRef<{ threadId: string; task: Promise<boolean> } | null>(null);
  const submittingThreads = useRef(new Set<string>());
  const draftNames = useRef(new Map<string, string>());
  const contextManagement = useContextManagement(serverThreadId, selection.store);
  const catalog = useConversationCatalog(initial, {
    setArchived: selection.store.setArchived,
    selectedIdRef: selection.selectedIdRef,
    loadSession: selection.loadSession,
    adoptSelection: selection.adoptSelection,
    clearSelection: selection.clearSelection,
    setCreatedSession: selection.setCreatedSession,
    cacheCreatedSession: selection.cacheCreatedSession,
    setSessionError: selection.setSessionError,
    selectSession: selection.selectSession,
  }, contextManagement.status.model);
  const runningModelRef = useRef(new Map<string, { turnId: string; model: string }>());
  const modelManager = useModels(serverThreadId, (threadId, result) => {
    if (result.threadId && result.threadId !== threadId) {
      contextManagement.applyModelSettings(result.threadId, result);
      if (selection.selectedIdRef.current === threadId) {
        selection.selectSession(result.threadId);
      }
    } else {
      contextManagement.applyModelSettings(threadId, result);
    }
    if (result.committed) void catalog.refreshSessions(false, undefined, false);
  }, contextManagement.status.model);
  const modelDefaults = useModelDefaults();
  const recordedModel = contextManagement.status.threadId === selection.selectedId ? contextManagement.status.model : "";
  const sessionModel = (selection.session?.threadId === selection.selectedId ? selection.session.model || "" : "")
    || catalog.sessions.find((item) => item.threadId === selection.selectedId)?.model
    || "";
  const recordedEffort = contextManagement.status.threadId === selection.selectedId ? contextManagement.status.reasoningEffort : "";
  const sessionEffort = (selection.session?.threadId === selection.selectedId ? selection.session.reasoningEffort || "" : "")
    || catalog.sessions.find((item) => item.threadId === selection.selectedId)?.reasoningEffort
    || "";
  const visibleModel = resolveVisibleModel(modelManager.models, modelDefaults, recordedModel, sessionModel);
  if (execution.status.active && execution.status.threadId === selection.selectedId) {
    const previous = runningModelRef.current.get(selection.selectedId);
    if (!previous || !previous.model || previous.turnId !== execution.status.turnId) runningModelRef.current.set(selection.selectedId, { turnId: execution.status.turnId, model: recordedModel || sessionModel });
  } else runningModelRef.current.delete(selection.selectedId);
  const usageModel = execution.status.active ? runningModelRef.current.get(selection.selectedId)?.model || '' : visibleModel;
  const draftSettingsRef = useRef(new Map<string, { model: string; reasoningEffort: string }>());
  const visibleEffort = draftSettingsRef.current.get(selection.selectedId)?.reasoningEffort
    ?? resolveVisibleEffort(modelManager.models, modelDefaults, visibleModel, recordedEffort || sessionEffort);
  const modelChoiceRef = useRef({ threadId: "", recordedModel: "", sessionModel: "", recordedEffort: "", contextSettled: false });
  modelChoiceRef.current = {
    threadId: selection.selectedId,
    recordedModel,
    sessionModel,
    recordedEffort,
    contextSettled: contextManagement.status.threadId === selection.selectedId
      && !selection.loadingSession
      && (selection.store.synced.has(selection.selectedId) || Boolean(contextManagement.status.updatedAt) || contextManagement.status.phase === "failed"),
  };
  const catalogModelsRef = useRef(modelManager.models);
  catalogModelsRef.current = modelManager.models;
  const stageUnrecordedModel = useCallback(async (threadId: string, applyVisible = false) => {
    const choice = modelChoiceRef.current;
    if (choice.threadId !== threadId || selection.selectedIdRef.current !== threadId) throw new Error("对话已切换，消息未发送");
    if (!choice.contextSettled) {
      if (applyVisible) throw new Error("模型设置还在读取中，请稍后再发送");
      return false;
    }
    const defaults = readModelDefaults();
    const shownModel = resolveVisibleModel(catalogModelsRef.current, defaults, choice.recordedModel, choice.sessionModel);
    const shownEffort = resolveVisibleEffort(catalogModelsRef.current, defaults, shownModel, choice.recordedEffort);
    const modelNeedsWrite = Boolean(shownModel && (applyVisible || (!choice.recordedModel && !choice.sessionModel)));
    const effortNeedsWrite = Boolean(shownEffort && shownEffort !== choice.recordedEffort);
    if (!modelNeedsWrite && !effortNeedsWrite) return false;
    const staged = modelNeedsWrite
      ? await modelManager.change(shownModel, shownEffort || undefined, threadId)
      : await modelManager.changeReasoningEffort(shownEffort, threadId);
    if (!staged) throw new Error("模型设置没有生效，请重试");
    return true;
  }, [modelManager.change, modelManager.changeReasoningEffort, selection.selectedIdRef]);

  const refreshUserInput = useCallback(async (_signal?: AbortSignal) => {
    const id = selection.selectedIdRef.current;
    if (id && !isPendingThread(id)) await selection.loadSession(id);
  }, [selection.loadSession]);

  const answerUserInput = useCallback(async (answers: Record<string, { answers: string[] }>) => {
    const request = userInputRequest;
    if (!request || userInputBusy) return false;
    setUserInputBusy(true);
    setUserInputError("");
    try {
      await executionApi.answerUserInput(request.threadId, request.requestId, answers);
      selection.store.update(request.threadId, current => ({ userInputRequest: String(current.userInputRequest?.requestId) === String(request.requestId) ? null : current.userInputRequest }));
      return true;
    } catch (error) {
      setUserInputError(error instanceof Error ? error.message : "提交失败，请重试");
      await refreshUserInput();
      return false;
    } finally {
      setUserInputBusy(false);
    }
  }, [refreshUserInput, userInputBusy, userInputRequest]);

  const syncLocation = useCallback(async () => {
    const params = new URLSearchParams(window.location.search);
    const requestedArchived = params.get("archived") === "1";
    if (requestedArchived !== catalog.archivedView) {
      await catalog.setArchiveViewMode(requestedArchived);
      return;
    }
    const requestedId = params.get("thread") || "";
    const currentId = selection.selectedIdRef.current;
    if (!requestedId) {
      if (currentId) selection.clearSelection();
      await catalog.refreshSessions(false, undefined, false);
      return;
    }
    if (requestedId !== currentId) {
      await selection.adoptSelection(requestedId);
    } else {
      await selection.loadSession(requestedId);
    }
    await catalog.refreshSessions(false, requestedId, false);
  }, [catalog.archivedView, catalog.refreshSessions, catalog.setArchiveViewMode, selection.adoptSelection, selection.clearSelection, selection.loadSession, selection.selectedIdRef]);

  const syncLocationRef = useRef(syncLocation);
  syncLocationRef.current = syncLocation;
  const locationKeyRef = useRef(conversationLocationKey());
  locationKeyRef.current = conversationLocationKey();

  useEffect(() => {
    const handleNavigation = () => {
      const nextLocationKey = conversationLocationKey();
      if (nextLocationKey === locationKeyRef.current) return;
      locationKeyRef.current = nextLocationKey;
      void syncLocationRef.current();
    };
    window.addEventListener("popstate", handleNavigation);
    window.addEventListener("negus:navigate", handleNavigation);
    return () => {
      window.removeEventListener("popstate", handleNavigation);
      window.removeEventListener("negus:navigate", handleNavigation);
    };
  }, []);

  useEffect(() => {
    editingMessageRef.current = editingMessage;
  }, [editingMessage]);

  const pendingCreatesRef = useRef(new Map<string, Promise<string>>());
  const deferredCreatesRef = useRef(new Map<string, () => Promise<string>>());
  const openingNewSessionRef = useRef(false);
  const waitForThread = useCallback(async (threadId: string, waitForContext = false) => {
    if (!isPendingThread(threadId)) return threadId;
    const deferred = deferredCreatesRef.current.get(threadId);
    if (deferred && !pendingCreatesRef.current.has(threadId)) {
      const task = deferred();
      pendingCreatesRef.current.set(threadId, task);
      void task.then(id => {
        if (id) deferredCreatesRef.current.delete(threadId);
        else pendingCreatesRef.current.delete(threadId);
      }).catch(() => { pendingCreatesRef.current.delete(threadId); });
    }
    const realId = await (pendingCreatesRef.current.get(threadId) || Promise.resolve(""));
    if (realId && waitForContext) {
      const started = Date.now();
      while (Date.now() - started < 8000 && selection.selectedIdRef.current === realId) {
        if (modelChoiceRef.current.threadId === realId && modelChoiceRef.current.contextSettled) return realId;
        await new Promise(resolve => window.setTimeout(resolve, 40));
      }
      return "";
    }
    return realId || "";
  }, [selection.selectedIdRef]);

  const setGoal = useCallback(async (objective: string, attachments: MediaFile[] = [], appendTranscript = true) => {
    const requestedId = selection.selectedIdRef.current;
    const threadId = await waitForThread(requestedId, true);
    if (!threadId || selection.selectedIdRef.current !== threadId) return false;
    try {
      if (!execution.status.active) {
        await stageUnrecordedModel(threadId, true);
        await modelManager.applyPending(threadId);
      }
      if (selection.selectedIdRef.current !== threadId) return false;
      const message = appendTranscript ? { ...createOptimisticMessage("/goal " + objective, attachments, createSubmissionId()), source: "native-goal" } : null;
      if (message) {
        selection.addOptimisticMessage(threadId, message);
        setLocalSendVersion(value => value + 1);
      }
      const result = await goal.update({ objective, status: "active", attachmentIds: attachments.map(file => file.id),
        ...(message ? { submissionId: message.submissionId } : {}) }, threadId);
      if (!result) {
        if (message) selection.updateOptimisticMessage(threadId, message.id, { deliveryState: "failed", deliveryError: "目标设置未确认" });
        return false;
      }
      void catalog.refreshSessions(false, threadId, false);
      return true;
    } catch (error) {
      if (selection.selectedIdRef.current === threadId) selection.setSessionError(presentConversationError(error));
      return false;
    }
  }, [waitForThread, selection.selectedIdRef, selection.addOptimisticMessage, selection.setSessionError, execution.status.active, stageUnrecordedModel, modelManager.applyPending, goal.update, catalog.refreshSessions]);

  const reconcileMessage = useCallback(async (threadId: string, messageId: string, submissionId: string, scope: string) => {
    if (reconcilingSubmissionsRef.current.has(submissionId) || reconciledSubmissionsRef.current.has(submissionId)) return;
    reconcilingSubmissionsRef.current.add(submissionId);
    try {
      for (let attempt = 0; attempt < 30; attempt += 1) {
        const result = await executionApi.submissionStatus(threadId, submissionId, undefined, scope).catch(() => null);
        if (reconciledSubmissionsRef.current.has(submissionId)) return;
        if (result?.status === "accepted" || result?.status === "failed") {
          selection.updateOptimisticMessage(threadId, messageId, {
            deliveryState: result.status === "failed" ? "failed" : undefined,
            ...(result.error ? { deliveryError: result.error, deliveryState: /active writer/iu.test(result.error) ? "occupied" : "failed" } : {}),
            ...(result.turnId ? { turnId: result.turnId } : {}),
          });
          if (result.status === "accepted") {
            catalog.updateSessionSummary({ threadId, updatedAt: new Date().toISOString() });
            await selection.loadSession(threadId, { retry: false, recovery: true, conversationId: scope });
          }
          return;
        }
        await new Promise(resolve => window.setTimeout(resolve, 2000));
      }
      if (reconciledSubmissionsRef.current.has(submissionId)) return;
      selection.updateCurrentSession(threadId, current => ({ ...current, messages: current.messages.map(message =>
        message.id === messageId ? { ...message, deliveryState: "pending" } : message) }));
    } finally {
      reconciledSubmissionsRef.current.add(submissionId);
      reconcilingSubmissionsRef.current.delete(submissionId);
    }
  }, [selection.updateCurrentSession, selection.updateOptimisticMessage, selection.loadSession, catalog.updateSessionSummary]);

  const sendDirectMessage = useCallback(async (text: string, attachments: MediaFile[] = [], existingSubmissionId = "", replacingMessageId = "") => {
    const messageText = text.trim();
    const requestedThreadId = selection.selectedId;
    if ((!messageText && !attachments.length) || !requestedThreadId || submittingThreads.current.has(requestedThreadId)) return false;
    submittingThreads.current.add(requestedThreadId);
    const settings = { model: visibleModel, reasoningEffort: visibleEffort };
    const scope = conversationScope;
    let threadId = requestedThreadId;
    const submissionId = existingSubmissionId || createSubmissionId();
    const optimisticMessage = { ...createOptimisticMessage(messageText, attachments, submissionId), deliveryState: "preparing" as const };
    if (replacingMessageId) selection.removeOptimisticMessage(threadId, replacingMessageId);
    reconciledSubmissionsRef.current.delete(submissionId);
    selection.addOptimisticMessage(threadId, optimisticMessage);
    setLocalSendVersion(value => value + 1);
    const updateDelivery = (deliveryState: "pending" | "failed" | "occupied" | undefined, turnId?: string, deliveryError?: string) => {
      if (deliveryState && reconciledSubmissionsRef.current.has(submissionId)) return;
      selection.updateOptimisticMessage(threadId, optimisticMessage.id, { deliveryState, deliveryError, ...(turnId ? { turnId } : {}) });
    };
    try {
      modelManager.clearPending(requestedThreadId);
      if (isPendingThread(requestedThreadId)) draftSettingsRef.current.set(requestedThreadId, settings);
      const created = await waitForThread(requestedThreadId);
      if (!created) throw new Error("新对话创建失败，请重试");
      if (created !== threadId) {
        selection.removeOptimisticMessage(threadId, optimisticMessage.id);
        threadId = created;
        submittingThreads.current.add(threadId);
        selection.addOptimisticMessage(threadId, optimisticMessage);
      }
      if (!selection.store.get(threadId).executionStatus.active) {
        try {
          const result = await modelApi.update(threadId, settings.model, undefined, settings.reasoningEffort, scope);
          if (result.threadId && result.threadId !== threadId) {
            selection.removeOptimisticMessage(threadId, optimisticMessage.id);
            const previous = threadId;
            threadId = result.threadId;
            selection.addOptimisticMessage(threadId, optimisticMessage);
            if (selection.selectedIdRef.current === previous) selection.selectSession(threadId);
          }
          if (settings.reasoningEffort) await modelApi.updateReasoningEffort(threadId, settings.reasoningEffort, undefined, scope);
          contextManagement.markSubmitted(threadId, settings);
        } catch (error) {
          // A turn may start between the two settings requests. The message endpoint
          // decides whether to start or steer; settings contention is not send failure.
          if (!(error instanceof Error) || !/^当前任务运行中，请在完成后(?:调整推理强度|切换模型)$/.test(error.message)) throw error;
        }
      }
      selection.updateOptimisticMessage(threadId, optimisticMessage.id, { deliveryState: "sending" });
      const attempt = await execution.sendMessage(messageText, attachments.map(file => file.id), submissionId, threadId, scope);
      if (!attempt || attempt.outcome === "failed") {
        const reason = attempt?.error || "发送失败";
        updateDelivery(/already has an active writer/iu.test(reason) ? "occupied" : "failed", undefined, reason);
        return true;
      }
      if (attempt.outcome === "uncertain") {
        updateDelivery("pending");
        void reconcileMessage(threadId, optimisticMessage.id, submissionId, scope);
        return true;
      }
      if (attempt.result.threadId !== threadId) {
        selection.removeOptimisticMessage(threadId, optimisticMessage.id);
        threadId = attempt.result.threadId;
        selection.addOptimisticMessage(threadId, optimisticMessage);
      }
      updateDelivery(undefined, attempt.result.turnId);
      catalog.updateSessionSummary({ threadId, updatedAt: new Date().toISOString() });
      void selection.loadSession(threadId, { retry: false, conversationId: scope });
      return true;
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error);
      updateDelivery(/already has an active writer/iu.test(reason) ? "occupied" : "failed", undefined, reason);
      return true;
    } finally {
      submittingThreads.current.delete(requestedThreadId);
      submittingThreads.current.delete(threadId);
    }
  }, [selection.selectedId, visibleModel, visibleEffort, conversationScope, waitForThread, execution.status.active, execution.sendMessage,
    selection.addOptimisticMessage, selection.removeOptimisticMessage, selection.updateCurrentSession, selection.selectSession, selection.loadSession, selection.updateOptimisticMessage, selection.setSessionError, contextManagement.markSubmitted, modelManager.clearPending, reconcileMessage, catalog.updateSessionSummary]);

  useEffect(() => {
    const threadId = selection.selectedId;
    if (!threadId || isPendingThread(threadId)) return;
    for (const message of selection.session?.messages || []) {
      if (message.id.startsWith("optimistic-") && message.submissionId && (!message.deliveryState || message.deliveryState === "pending")) {
        void reconcileMessage(threadId, message.id, message.submissionId, conversationScope);
      }
    }
  }, [selection.selectedId, selection.session, conversationScope, reconcileMessage]);

  const retryPendingMessage = useCallback(async (message: SessionMessage) => {
    if (!message.submissionId || retryingMessageId) return false;
    setRetryingMessageId(message.id);
    try {
      return await sendDirectMessage(message.text, attachmentsFromMessage(message), message.deliveryState === "failed" ? "" : message.submissionId, message.id);
    } finally {
      setRetryingMessageId("");
    }
  }, [retryingMessageId, sendDirectMessage]);

  const sendMessage = useCallback(async (text: string, attachments: MediaFile[] = []) => {
    const target = editingMessageRef.current;
    if (!target) return sendDirectMessage(text, attachments);
    const threadId = selection.selectedIdRef.current;
    if (!threadId || !target.turnId || target.role !== "user" || execution.status.active || selection.session?.archived) return false;
    setForkingMessageId(target.id);
    try {
      await conversationApi.revert(threadId, target.protocolTurnId || target.turnId);
      selection.store.clearCompletedMessages(threadId);
      selection.cancelSessionLoad(threadId);
      setHistoryEdit(previous => ({ threadId, revision: (previous?.revision || 0) + 1 }));
      selection.updateCurrentSession(threadId, current => {
        const index = current.messages.findIndex(message => message.id === target.id);
        return { ...current, contentVersion: undefined, messages: index < 0 ? current.messages : current.messages.slice(0, index) };
      });
      setEditingMessage(null);
      editingMessageRef.current = null;
      return await sendDirectMessage(text, attachments);
    } finally {
      setForkingMessageId("");
    }
  }, [execution.status.active, selection.selectedIdRef, selection.session, selection.cancelSessionLoad, selection.updateCurrentSession, sendDirectMessage]);

  const beginEditMessage = useCallback((message: SessionMessage) => {
    if (message.role !== "user" || !message.turnId || selection.session?.archived) return;
    editingMessageRef.current = message;
    setEditingMessage(message);
  }, [selection.session?.archived]);

  const cancelEditMessage = useCallback(() => {
    editingMessageRef.current = null;
    setEditingMessage(null);
  }, []);

  const renameSession = useCallback(async (name: string) => {
    const threadId = selection.selectedIdRef.current;
    const normalized = name.trim();
    if (!threadId || !normalized || normalized.length > 120 || renaming) return false;
    if (isPendingThread(threadId)) {
      draftNames.current.set(threadId, normalized);
      selection.updateCurrentSession(threadId, current => ({ ...current, title: normalized }));
      return true;
    }
    setRenaming(true);
    try {
      const renamed = await conversationApi.rename(threadId, normalized);
      selection.updateCurrentSession(threadId, (current) => ({
        ...current,
        ...renamed,
        title: renamed.title || normalized,
      }));
      catalog.updateSessionSummary(renamed);
      window.dispatchEvent(new CustomEvent("negus:session-renamed", { detail: renamed }));
      return true;
    } catch {
      return false;
    } finally {
      setRenaming(false);
    }
  }, [catalog.updateSessionSummary, renaming, selection.selectedIdRef, selection.updateCurrentSession]);

  useEffect(() => {
    const renamed = (event: Event) => {
      const summary = (event as CustomEvent<SessionSummary>).detail;
      if (!summary?.threadId) return;
      selection.updateCurrentSession(summary.threadId, current => ({ ...current, ...summary }));
      catalog.updateSessionSummary(summary);
    };
    window.addEventListener("negus:session-renamed", renamed);
    return () => window.removeEventListener("negus:session-renamed", renamed);
  }, [selection.updateCurrentSession, catalog.updateSessionSummary]);

  useEffect(() => {
    if (!editingMessageRef.current) return;
    editingMessageRef.current = null;
    setEditingMessage(null);
  }, [selection.selectedId]);

  const forkFromMessage = useCallback(async (message: SessionMessage) => {
    const threadId = selection.selectedIdRef.current;
    if (!threadId || !message.turnId || (execution.status.active && (!execution.status.turnId || message.turnId === execution.status.turnId)) || selection.session?.archived) return false;
    setForkingMessageId(message.id);
    try {
      return await catalog.forkSession(threadId, message.turnId);
    } finally {
      setForkingMessageId("");
    }
  }, [catalog.forkSession, execution.status.active, execution.status.turnId, selection.selectedIdRef, selection.session?.archived]);

  const queueMessage = useCallback(async (text: string, attachments: MediaFile[] = []) => {
    const messageText = text.trim();
    if (!messageText && !attachments.length) return false;
    const settings = { model: visibleModel, reasoningEffort: visibleEffort };
    const threadId = await waitForThread(selection.selectedId);
    if (!threadId) return false;
    return followUpQueue.enqueue(messageText, attachments, threadId, settings);
  }, [followUpQueue.enqueue, selection.selectedId, visibleModel, visibleEffort, waitForThread]);

  const openNewSession = useCallback((projectRoot = "", requestedModel = "", requestedProviderId = "", options: { deferred?: boolean; onCreated?: (threadId: string) => void } = {}) => {
    if (openingNewSessionRef.current) return false;
    openingNewSessionRef.current = true;
    const defaults = readModelDefaults();
    const models = readModelCatalog();
    const model = requestedModel || resolveVisibleModel(models, defaults, "", "");
    const entry = models.find((item) => item.model === model);
    const providerId = requestedProviderId || (entry ? providerIdOf(entry) : defaults.providerId);
    const pendingId = `pending:${createClientId("new")}`;
    selection.setCreatedSession({
      threadId: pendingId,
      source: "codex",
      title: "新对话",
      updatedAt: new Date().toISOString(),
      messageCount: 0,
      latestUser: "",
      latestAssistant: "",
      archived: false,
      readOnly: false,
      cwd: projectRoot,
      model,
      messages: [],
    });
    const create = () => {
      const draft = draftSettingsRef.current.get(pendingId);
      const chosenModel = draft?.model || model;
      const chosenEntry = readModelCatalog().find(entry => entry.model === chosenModel);
      const chosenProvider = draft && chosenEntry ? providerIdOf(chosenEntry) : providerId;
      return catalog.createSession(projectRoot, chosenModel, pendingId, chosenProvider, true).then(async (created) => {
        if (created) contextManagement.applyModelSettings(created, {
          model: chosenModel,
          reasoningEffort: draft?.reasoningEffort || resolveVisibleEffort(models, defaults, chosenModel, ""),
        });
        if (created && draftNames.current.has(pendingId)) {
          const renamed = await conversationApi.rename(created, draftNames.current.get(pendingId)!).catch(() => {
            if (selection.selectedIdRef.current === created) selection.setSessionError("对话已创建，但标题保存失败，请重新命名");
            return null;
          });
          if (renamed) {
            selection.updateCurrentSession(created, current => ({ ...current, ...renamed }));
            catalog.updateSessionSummary(renamed);
            draftNames.current.delete(pendingId);
          }
        }
        if (created) options.onCreated?.(created);
        return created || "";
      });
    };
    if (options.deferred) {
      deferredCreatesRef.current.set(pendingId, create);
      openingNewSessionRef.current = false;
      return true;
    }
    const task = create();
    pendingCreatesRef.current.set(pendingId, task);
    void task.finally(() => {
      openingNewSessionRef.current = false;
    });
    return true;
  }, [catalog.createSession, selection.setCreatedSession]);

  const prepareDesktopConversation = useCallback((projectRoot: string) => {
    if (desktopPreparingRef.current) return desktopPreparingRef.current;
    const task = (async () => {
      if (!projectRoot) return false;
      const key = `negus:desktop-thread:v1:${projectRoot}`;
      const saved = readLocalCache(key, (value): value is string => typeof value === "string");
      if (saved) {
        // A partial/stale list must not create a replacement conversation.
        const existing = await conversationApi.session(saved).catch((error: unknown) => {
          if (error instanceof HttpError && error.status === 404) return null;
          throw error;
        });
        if (existing && !("messages" in existing)) return false;
        if (existing && existing.cwd?.replace(/\\/g, "/") !== projectRoot.replace(/\\/g, "/")) return false;
        if (existing && !existing.archived && !existing.readOnly) {
          selection.selectSession(existing.threadId);
          return true;
        }
      }
      setEditingMessage(null);
      editingMessageRef.current = null;
      return openNewSession(projectRoot, "", "", {
        deferred: true,
        onCreated: id => writeLocalCache(key, id),
      });
    })().catch(() => false);
    desktopPreparingRef.current = task;
    void task.finally(() => { desktopPreparingRef.current = null; });
    return task;
  }, [openNewSession, selection.selectSession]);

  const review = useCallback(async () => {
    const threadId = selection.selectedIdRef.current;
    if (!threadId || execution.status.active || selection.session?.archived) return false;
    try {
      await executionApi.review(threadId);
      await execution.refreshStatus(undefined, true);
      return true;
    } catch {
      return false;
    }
  }, [execution.refreshStatus, execution.status.active, selection.selectedIdRef, selection.session?.archived]);

  const onSessionsChanged = useCallback((threadId?: string | string[]) => {
    window.dispatchEvent(new Event('negus:directory-changed'));
    return catalog.refreshSessions(false, typeof threadId === 'string' ? threadId : undefined, false);
  }, [catalog.refreshSessions]);

  const providerOf = useCallback((model: string) => {
    const entry = modelManager.models.find((item) => item.model === model);
    return {
      id: entry ? providerIdOf(entry) : model.includes("::") ? model.split("::")[0] : "current",
      name: entry?.providerDisplayName || entry?.displayName || "",
    };
  }, [modelManager.models]);

  const changeModel = useCallback(async (model: string, reasoningEffort?: string) => {
    const threadId = selection.selectedIdRef.current;
    if (isPendingThread(threadId)) {
      draftSettingsRef.current.set(threadId, { model, reasoningEffort: reasoningEffort ?? visibleEffort });
      selection.updateCurrentSession(threadId, current => ({ ...current, model }));
      return true;
    }
    const source = providerOf(visibleModel);
    const target = providerOf(model);
    const employeeScoped = Boolean(new URLSearchParams(window.location.search).get("agent"));
    if (threadId && !employeeScoped && visibleModel && source.id !== target.id) {
      if (execution.status.active) {
        selection.setSessionError("当前任务完成后再切换配置");
        return false;
      }
      setProviderSwitchError("");
      setProviderSwitch({
        threadId,
        title: selection.session?.title || "当前对话",
        model,
        reasoningEffort: reasoningEffort ?? visibleEffort,
        providerName: target.name || target.id,
      });
      return true;
    }
    return modelManager.change(model, reasoningEffort);
  }, [execution.status.active, modelManager.change, providerOf, selection.selectedIdRef, selection.session?.title, selection.setSessionError, selection.updateCurrentSession, visibleEffort, visibleModel]);

  const cancelProviderSwitch = useCallback(() => {
    const request = providerSwitch;
    if (!request) return false;
    const previous = contextManagement.status.lastSuccessfulSettings || {
      model: visibleModel,
      reasoningEffort: visibleEffort,
    };
    modelManager.clearPending(request.threadId);
    draftSettingsRef.current.delete(request.threadId);
    contextManagement.applyModelSettings(request.threadId, { ...previous, committed: true });
    setProviderSwitch(null);
    setProviderSwitchError("");
    return true;
  }, [contextManagement.applyModelSettings, contextManagement.status.lastSuccessfulSettings, modelManager.clearPending, providerSwitch, visibleEffort, visibleModel]);

  const confirmProviderSwitch = useCallback(async () => {
    const request = providerSwitch;
    if (!request || providerSwitchBusy) return false;
    setProviderSwitchBusy(true);
    setProviderSwitchError("");
    try {
      const result = await modelApi.copyToProvider(request.threadId, request.model, request.reasoningEffort, conversationScope);
      catalog.updateSessionSummary(result.session);
      contextManagement.applyModelSettings(result.session.threadId, {
        model: result.model,
        reasoningEffort: result.reasoningEffort,
        committed: true,
      });
      await selection.loadSession(result.session.threadId);
      selection.selectSession(result.session.threadId);
      void catalog.refreshSessions(false, result.session.threadId, false);
      setProviderSwitch(null);
      return true;
    } catch (reason) {
      setProviderSwitchError(reason instanceof Error ? reason.message : "创建新对话失败");
      return false;
    } finally {
      setProviderSwitchBusy(false);
    }
  }, [catalog.refreshSessions, catalog.updateSessionSummary, contextManagement.applyModelSettings, conversationScope, providerSwitch, providerSwitchBusy, selection.loadSession, selection.selectSession]);

  const handleEvent = useCallback((event: ProjectEvent) => {
    if (!selection.store.acceptEvent(event)) return;
    if (event.type === "assistant_message_completed") selection.store.completeMessage(event.threadId, event.message);
    const previousStatus = event.type === 'execution_status' ? selection.store.get(event.threadId).executionStatus : null;
    execution.handleEvent(event);
    if (event.type === 'execution_status' && event.threadId !== selection.selectedIdRef.current) selection.store.update(event.threadId, { executionStatus: event }, true);
    if (event.type === 'execution_status' && event.threadId !== selection.selectedIdRef.current
      && ['completed', 'failed', 'interrupted', 'systemError'].includes(event.phase)
      && (previousStatus?.phase !== event.phase || previousStatus?.turnId !== event.turnId)) {
      selection.store.freshBodies.add(event.threadId);
      selection.store.invalidate(event.threadId, false);
    }
    if ((event as { type: string }).type === 'employee_status' || (event as { type: string }).type === 'employee_message_completed') window.dispatchEvent(new Event('negus:directory-changed'));
    const acceptedQueueItem = followUpQueue.handleEvent(event);
    goal.handleEvent(event);
    if (event.type === "context_status") contextManagement.handleEvent(event);
    if (event.type === "user_message_accepted") {
      if (acceptedQueueItem) {
        const message = createOptimisticMessage(acceptedQueueItem.text, acceptedQueueItem.attachments, event.submissionId, acceptedQueueItem.sentAt || undefined);
        selection.addOptimisticMessage(event.threadId, { ...message, turnId: event.turnId, serverTimestamp: Boolean(acceptedQueueItem.sentAt),
          authorId: acceptedQueueItem.authorId, authorName: acceptedQueueItem.authorName, displaySourceAgentId: acceptedQueueItem.displaySourceAgentId });
      }
      reconciledSubmissionsRef.current.add(event.submissionId);
      selection.updateOptimisticMessage(event.threadId, `optimistic-${event.submissionId}`, { deliveryState: undefined, deliveryError: undefined, turnId: event.turnId, protocolTurnId: event.turnId });
    }
    if (event.type === "execution_status" && event.phase === "completed"
      && (previousStatus?.phase !== event.phase || previousStatus?.turnId !== event.turnId)) contextManagement.completeSettings(event.threadId);
    if (event.type === "user_message_submitted") {
      if (event.queueSubmissionId) selection.store.linkQueuedMessage(event.threadId, event.queueSubmissionId, event.submissionId);
      selection.updateOptimisticMessage(event.threadId, event.messageId || `optimistic-${event.submissionId}`, { createdAt: event.createdAt, serverTimestamp: true });
      const generated = createOptimisticMessage(
        event.text,
        event.attachments || [],
        event.submissionId,
        event.createdAt,
      );
      const message = { ...generated, id: event.messageId || generated.id, deliveryState: reconciledSubmissionsRef.current.has(event.submissionId) ? undefined : "pending" as const, serverTimestamp: true,
        ...(event.displaySourceAgentId ? { authorId: event.authorId, authorName: event.authorName, displaySourceAgentId: event.displaySourceAgentId } : {}) };
      selection.addOptimisticMessage(event.threadId, message);
    }
    if (event.type === 'user_input_requested') {
      if (event.threadId === selection.selectedIdRef.current) setUserInputError('');
      selection.store.invalidate(event.threadId, false);
      selection.store.update(event.threadId, { userInputRequest: event.request }, true);
    }
    if (event.type === 'user_input_resolved') selection.store.update(event.threadId, current => ({
      userInputRequest: String(current.userInputRequest?.requestId) === String(event.requestId) ? null : current.userInputRequest }), true);
  }, [contextManagement.handleEvent, execution.handleEvent, followUpQueue.handleEvent, goal.handleEvent, selection.addOptimisticMessage, selection.updateOptimisticMessage, selection.selectedIdRef]);
  const recoverRealtime = useCallback((_reason: RealtimeRecoveryReason) => {
    const threadId = selection.selectedIdRef.current;
    const pending = realtimeRecoveryRef.current;
    if (pending?.threadId === threadId) return pending.task;
    window.dispatchEvent(new Event('negus:realtime-recovered'));
    const task = (async () => {
      const session = threadId && !isPendingThread(threadId)
        ? selection.loadSession(threadId, { recovery: true })
        : Promise.resolve(false);
      const [, result] = await Promise.allSettled([onSessionsChanged(), session]);
      return result.status === 'fulfilled' && result.value === true;
    })();
    realtimeRecoveryRef.current = { threadId, task };
    void task.finally(() => {
      if (realtimeRecoveryRef.current?.task === task) realtimeRecoveryRef.current = null;
    });
    return task;
  }, [onSessionsChanged, selection.loadSession, selection.selectedIdRef]);
  const connected = useConversationEvents(
    onSessionsChanged,
    handleEvent,
    recoverRealtime,
    selection.selectedId,
    execution.status.active,
    execution.status.phase === "submitted",
  );

  const selectLatestSession = useCallback((projectRoot = "") => {
    const desktopThreadId = projectRoot
      ? readLocalCache("negus:desktop-thread:v1:" + projectRoot, (value): value is string => typeof value === "string") || ""
      : "";
    catalog.selectLatestSession(desktopThreadId);
  }, [catalog.selectLatestSession]);

  return {
    store: selection.store,
    project: catalog.project,
    sessions: catalog.sessions,
    archivedView: catalog.archivedView,
    selectedId: selection.selectedId,
    composerKey: selection.composerKey,
    session: selection.session,
    cachedSessions: selection.cachedSessions,
    loadingList: catalog.loadingList,
    initialSyncReady: catalog.initialSyncReady,
    loadingSession: selection.loadingSession,
    loadingOlder: selection.loadingOlder,
    syncing: selection.syncing,
    contentSyncState: selection.contentSyncState,
    connected,
    listError: catalog.listError,
    sessionError: selection.sessionError,
    selectSession: selection.selectSession,
    selectLatestSession,
    createSession: catalog.createSession,
    openNewSession,
    creating: catalog.creating,
    setArchiveViewMode: catalog.setArchiveViewMode,
    archiveSession: catalog.archiveSession,
    unarchiveSession: catalog.unarchiveSession,
    archiveBusyIds: catalog.archiveBusyIds,
    providerSwitch,
    providerSwitchBusy,
    providerSwitchError,
    confirmProviderSwitch,
    cancelProviderSwitch,
    forkFromMessage,
    forkingMessageId,
    editingMessage,
    editingMessageId: editingMessage?.id || "",
    retryPendingMessage,
    retryingMessageId,
    localSendVersion,
    historyEdit,
    beginEditMessage,
    cancelEditMessage,
    renameSession,
    renaming,
    loadOlder: selection.loadOlder,
    executionStatus: execution.status,
    streamingText: execution.streamingText,
    commentaryText: execution.commentaryText,
    contextStatus: contextManagement.status,
    contextReady: contextManagement.ready,
    visibleModel,
    usageModel,
    visibleEffort,
    models: modelManager.models,
    modelsLoading: modelManager.loading,
    modelChanging: modelManager.changing,
    modelError: modelManager.error,
    sending: execution.sending,
    sendingSlow: execution.sendingSlow,
    sendMessage,
    prepareDesktopConversation,
    queueMessage,
    queueItems: followUpQueue.items,
    queueLoading: followUpQueue.loading,
    queueBusy: followUpQueue.busy,
    queueError: followUpQueue.error,
    removeQueueItem: followUpQueue.remove,
    moveQueueItem: followUpQueue.move,
    retryQueueItem: followUpQueue.retry,
    sendQueueItem: followUpQueue.sendNow,
    interrupt: () => !execution.status.active && goal.goal?.status === "active"
      ? goal.update({ status: "paused" }).then(Boolean)
      : execution.interrupt(),
    userInputRequest,
    userInputBusy,
    userInputError,
    answerUserInput,
    review,
    compactContext: contextManagement.compact,
    setAutoCompactThreshold: contextManagement.setThreshold,
    changeModel,
    changeReasoningEffort: async (reasoningEffort: string) => {
      const id = selection.selectedIdRef.current;
      if (!isPendingThread(id)) return modelManager.changeReasoningEffort(reasoningEffort);
      draftSettingsRef.current.set(id, { model: visibleModel, reasoningEffort });
      selection.updateCurrentSession(id, current => ({ ...current }));
      return true;
    },
    goal: goal.goal,
    goalBusy: goal.busy,
    goalError: goal.error,
    goalResumePrompt: goal.resumePrompt,
    dismissGoalResumePrompt: goal.dismissResumePrompt,
    setGoal,
    editGoal: (objective: string) => setGoal(objective, [], false),
    changeGoalStatus: async (status: "active" | "paused") => {
      const threadId = selection.selectedIdRef.current;
      if (status === "active") {
        try {
          if (!execution.status.active) {
            await stageUnrecordedModel(threadId, true);
            await modelManager.applyPending(threadId);
          }
          if (selection.selectedIdRef.current !== threadId) return false;
        } catch (error) {
          if (selection.selectedIdRef.current === threadId) selection.setSessionError(presentConversationError(error));
          return false;
        }
      }
      return Boolean(await goal.update({ status }, threadId));
    },
    clearGoal: () => goal.clear(),
    archivedByThread: catalog.archivedByThread,
    refresh: () => onSessionsChanged(),
  };
}

